class Solution {
public:
    long long evenProduct(std::vector<int>& nums) {
        long long last_even = -1;
        long long ans = 0;
        for (int i = 0; i < (int)nums.size(); ++i) {
            if (nums[i] % 2 == 0) last_even = i;
            ans += last_even + 1;
        }
        return ans;
    }
};

class Solution {
    public long evenProduct(int[] nums) {
        long lastEven = -1;
        long ans = 0;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] % 2 == 0) lastEven = i;
            ans += lastEven + 1;
        }
        return ans;
    }
}

var evenProduct = function(nums) {
    let lastEven = -1;
    let ans = 0;
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] % 2 === 0) lastEven = i;
        ans += lastEven + 1;
    }
    return ans;
};
